  "/usr/share/icons/Piloti/index.theme": "[Icon Theme]\nName=Piloti\nComment=Piloti icon theme: animated folders and documents, accent-colored icons\nInherits=Papirus,Adwaita,hicolor\nDirectories=animated/places,animated/mimetypes,animated/apps,animated/devices,scalable/apps,scalable/mimetypes\n\n# Accent-colored icons (read by Piloti Desktop, ignored by GTK and Qt).\n#\n# Icons that mark shapes with class=\"accent\", \"accent-darker\" or\n# \"accent-lighter\" (SVG), or `cl` set to those names (Lottie), follow the\n# desktop accent color, whatever theme they come from.\n#\n# InheritedIcons lists icons from inherited themes that carry no markers but\n# draw the accent with the colors below (stock Papirus blue). They are marked\n# when loaded. `*` matches any suffix.\n[X-Piloti Accent]\nAccent=#5294e2\nDarker=#4877b1\nLighter=#8bbcf6\nDarkerFactor=0.22\nLighterMix=0.4\nInheritedIcons=folder;folder-*;user-home;user-desktop;user-trash-full;system-file-manager;preferences-desktop;preferences-system;text-x-generic\n\n[animated/places]\nContext=Places\nSize=64\nMinSize=16\nMaxSize=512\nType=Scalable\n\n[animated/apps]\nContext=Applications\nSize=64\nMinSize=16\nMaxSize=512\nType=Scalable\n\n[animated/mimetypes]\nContext=MimeTypes\nSize=64\nMinSize=16\nMaxSize=512\nType=Scalable\n\n[animated/devices]\nContext=Devices\nSize=64\nMinSize=16\nMaxSize=512\nType=Scalable\n\n[scalable/apps]\nContext=Applications\nSize=128\nMinSize=16\nMaxSize=512\nType=Scalable\n\n[scalable/mimetypes]\nContext=MimeTypes\nSize=64\nMinSize=16\nMaxSize=512\nType=Scalable\n",
